#include <iostream>
#include <fstream>
int main() {
    std::ifstream file("example.txt");
    if (file.is_open()) {
        std::streamoff currentPos = file.tellg();  // Get current position as streamoff
        file.seekg(currentPos + 10);  // Seek forward by 10 units
        std::cout << "New position: " << file.tellg() << std::endl;
    }
    return 0;
}
